4: __kernel void kernel_main(kernel_arg_t* __UNIFORM__ arg) {
5:     const uint32_t row = blockIdx.x * blockDim.x + threadIdx.x;
6:     if (row >= arg->rows)
7:         return;
8:     auto weights = reinterpret_cast<const int8_t*>(arg->weights);
9:     auto scales = reinterpret_cast<const float*>(arg->scales);
10:     auto input = reinterpret_cast<const int8_t*>(arg->input);
11:     auto input_scales = reinterpret_cast<const float*>(arg->input_scales);
12:     auto output = reinterpret_cast<float*>(arg->output);
13:     const uint32_t groups = arg->columns / arg->group_size;
14:     float sum = 0.0f;
15:     for (uint32_t group = 0; group < groups; ++group) {
16:         int32_t partial = 0;
17:         for (uint32_t k = 0; k < arg->group_size; ++k) {
18:             uint32_t column = group * arg->group_size + k;
19:             partial += int32_t(input[column]) * int32_t(weights[row * arg->columns + column]);
20:         }
21:         sum += float(partial) * scales[row * groups + group] * input_scales[group];
22:     }
23:     output[row] = sum;
24: }

